INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4174c56b-ae14-475c-b9eb-1257651e4e2e', '5a7f2ae3-9bef-40cf-9fdb-5c403e594d6e', 0, 'The root key');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ff356b3a-f6b7-4845-9b5d-5be9fdefd821', '5a7f2ae3-9bef-40cf-9fdb-5c403e594d6e', 1, 'The snapshot key');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cb325783-4fa0-41cb-8e0a-424da0006f81', '5a7f2ae3-9bef-40cf-9fdb-5c403e594d6e', 2, 'The timestamp key');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d9317edb-cece-4f37-9640-3b72c022f33c', '5a7f2ae3-9bef-40cf-9fdb-5c403e594d6e', 3, 'The targets/delegation key');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('95da87c0-141b-40de-beea-673497f4cd40', '8b07870c-ce60-4db2-b7e0-cffed0f8323e', 0, 'It signs a short-lived timestamp file confirming the current metadata snapshot is still fresh, protecting against replay/freeze attacks; it''s kept server-side because it must be re-signed frequently (near-continuously)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f6b4b270-d1f4-40d2-aaa2-b9fd7d634421', '8b07870c-ce60-4db2-b7e0-cffed0f8323e', 1, 'It records the wall-clock time an image was built, for audit logging only');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('797edb11-3c4b-44ae-989a-d570a108db81', '8b07870c-ce60-4db2-b7e0-cffed0f8323e', 2, 'It encrypts the image layers during push');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d5907c15-82f7-4216-8dab-6675278ae70d', '8b07870c-ce60-4db2-b7e0-cffed0f8323e', 3, 'It authenticates the publisher''s Docker Hub login session');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('37c59eb5-d3f9-49b6-b39d-c851207fedee', '939645a2-809c-47a9-b7f6-2bdb2738779a', 0, 'They let specific team members or CI systems sign tags for a repository without ever having access to that repository''s root or targets key, limiting blast radius if one delegate''s key is compromised');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c4b20a5b-fd60-49d4-8543-f861ee0857a0', '939645a2-809c-47a9-b7f6-2bdb2738779a', 1, 'They let any authenticated Docker Hub user sign any repository''s images');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9a5447f6-2944-4cb7-ac94-55d0e592ab7f', '939645a2-809c-47a9-b7f6-2bdb2738779a', 2, 'They replace the need for a root key entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3d616495-8a06-474c-bac6-8d322039a547', '939645a2-809c-47a9-b7f6-2bdb2738779a', 3, 'They are used only to delegate registry storage across multiple regions');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('315fe479-9d1a-4bda-98b4-01da55690b87', 'acf4fe45-b54e-4b14-8de3-a24b6103bff4', 0, 'The pull fails with a trust/signature error — DCT enforces that only signed tags can be pulled when enabled');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('939bd8cc-e319-4ca1-b559-26321923e24d', 'acf4fe45-b54e-4b14-8de3-a24b6103bff4', 1, 'The pull succeeds, but with a warning printed to stderr');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('52c30fde-6d4e-4b48-8112-414c43c2a47d', 'acf4fe45-b54e-4b14-8de3-a24b6103bff4', 2, 'The pull succeeds, since DOCKER_CONTENT_TRUST only affects docker push, not docker pull');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4a9c4852-2579-4d78-8507-92c558321950', 'acf4fe45-b54e-4b14-8de3-a24b6103bff4', 3, 'The pull silently falls back to the '':latest'' tag if it is signed');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5a9b4caf-30d3-4d86-9223-cd213a40cc88', 'ac49bc5d-44a0-4cc4-a199-78f7128e6b7d', 0, 'It pushes the image (if not already pushed) and signs its manifest digest, publishing updated trust metadata so DCT-enforcing clients can verify that exact tag');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5109ffac-341d-4e9e-a852-b6f35a9d05a3', 'ac49bc5d-44a0-4cc4-a199-78f7128e6b7d', 1, 'It only signs the image locally without contacting any registry or trust server');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a62709a6-643f-4b18-b886-ea9c4fd1a077', 'ac49bc5d-44a0-4cc4-a199-78f7128e6b7d', 2, 'It generates a brand-new root key for the repository every time it''s run');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8a049781-7ae7-462d-99df-a2e60b17a0da', 'ac49bc5d-44a0-4cc4-a199-78f7128e6b7d', 3, 'It re-encrypts the image layers with the signer''s private key');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ef776539-a8be-41af-ae16-5f945ba6d6c3', 'ce808ea6-8b09-4b4d-8dad-1bdf3bfd035a', 0, 'That the image is free of vulnerabilities or malware — DCT proves who published/signed it and that the content is unaltered, not that the content is safe');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9d591d3a-680d-4f4f-b05e-f4bd2e2813ad', 'ce808ea6-8b09-4b4d-8dad-1bdf3bfd035a', 1, 'That the image manifest digest matches what was signed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c48611a0-152d-4d45-8f8c-cb6ac67e1263', 'ce808ea6-8b09-4b4d-8dad-1bdf3bfd035a', 2, 'That the signature chains back to a trusted root key');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5307c13f-277b-42d4-b449-2df24de2192a', 'ce808ea6-8b09-4b4d-8dad-1bdf3bfd035a', 3, 'That the metadata hasn''t been tampered with in transit');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('101a23ed-212d-42a4-b459-873e59b05e06', 'bb284420-c714-42b5-a87a-c4b7b2777e82', 0, 'Ordinary `docker pull`/`docker push` operations are unaffected by the DCT retirement — only DCT-specific trust operations (docker trust ..., DOCKER_CONTENT_TRUST=1 enforcement) stop working once the service is fully shut down');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f6fbd869-c9ec-42d6-9970-f051f3a42b32', 'bb284420-c714-42b5-a87a-c4b7b2777e82', 1, 'All Docker Hub image pulls will require re-signing under a new scheme before December 8, 2026');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('10f6c3b2-f40d-47c7-9b08-2e32c1a4d595', 'bb284420-c714-42b5-a87a-c4b7b2777e82', 2, 'The retirement only affects self-hosted registries, not Docker Hub');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4ad7ac86-e585-4520-99f3-da57eb168b91', 'bb284420-c714-42b5-a87a-c4b7b2777e82', 3, 'DCT is being replaced by a drop-in, API-compatible successor also called Notary, requiring no client changes');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3c65514d-e32c-4e5f-afac-0cccf3400542', '851dc82e-6b57-4f45-9d98-75c4fc9eb301', 0, 'Performs a local vulnerability analysis of the specified image (or the most recently built image if none is given), matching its SBOM against a vulnerability database and reporting CVEs');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ceccf7c9-9a6d-4d6c-ab8d-34483f771814', '851dc82e-6b57-4f45-9d98-75c4fc9eb301', 1, 'Uploads the image to Docker Hub for public scanning only');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('92756890-7829-4535-824c-eb18bd122df0', '851dc82e-6b57-4f45-9d98-75c4fc9eb301', 2, 'Lists the CVEs of every image ever pulled on the host, regardless of argument');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f056874a-b32d-49cb-a24c-8f0590b064d7', '851dc82e-6b57-4f45-9d98-75c4fc9eb301', 3, 'Deletes any image found to have a critical CVE');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('130890b2-cf80-43f8-ad27-55ce9b92a6b6', '2947d1cd-45ab-4eb0-aad9-b71e820319f3', 0, 'quickview gives a condensed summary (vulnerability counts plus base-image refresh/update recommendations) rather than the full per-CVE detail that cves reports');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('01d1cd23-ce90-409d-b4b9-00106489eab2', '2947d1cd-45ab-4eb0-aad9-b71e820319f3', 1, 'quickview only works against images already pushed to Docker Hub, cves works on any local image');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bdd0d35b-6da7-487e-a422-743c8496eefb', '2947d1cd-45ab-4eb0-aad9-b71e820319f3', 2, 'quickview scans for license issues only, never vulnerabilities');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e1dfec5a-d2d4-4413-ac6c-1c6842756368', '2947d1cd-45ab-4eb0-aad9-b71e820319f3', 3, 'There is no functional difference; quickview is a deprecated alias for cves');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('75a4870a-b240-464e-a55e-eea1999786f3', '45770205-c3bf-4da1-b488-12dfa8a056b4', 0, 'Analyzing and comparing two images (e.g. a new build vs. its previous release, or vs. a different base) to show what vulnerabilities/packages changed between them');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8625c3c1-77b3-473d-9eef-fbbca58e98ed', '45770205-c3bf-4da1-b488-12dfa8a056b4', 1, 'Comparing two Dockerfiles line-by-line for syntax differences');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0ee1dad3-ddfb-4d92-aad9-6f23fbede2be', '45770205-c3bf-4da1-b488-12dfa8a056b4', 2, 'Comparing CPU/memory resource usage between two running containers');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d520ef83-2e2a-4458-b206-727c06af0905', '45770205-c3bf-4da1-b488-12dfa8a056b4', 3, 'Comparing two Swarm services'' replica counts');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('24ebf8c6-6bf0-4778-9c50-5301a6fa20eb', '5bf4acb8-f7c7-4258-ae8d-281ba57ac159', 0, 'A Software Bill of Materials (SBOM) — an inventory of the packages/components actually present in the image');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2756128d-fbc0-466a-b581-b9b4994bf6b3', '5bf4acb8-f7c7-4258-ae8d-281ba57ac159', 1, 'A full decompilation of every binary in the image');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('17203170-9047-43aa-97eb-3037adb6815d', '5bf4acb8-f7c7-4258-ae8d-281ba57ac159', 2, 'A checksum of the entire image tarball only');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('79f7aec9-345b-4946-843e-13f08d39f637', '5bf4acb8-f7c7-4258-ae8d-281ba57ac159', 3, 'A list of every Dockerfile instruction used to build the image');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('969efb77-b50f-4b3b-a75d-1effe160b626', '363c75b1-7691-4d38-ab66-244551f2f8b5', 0, 'Filter/prioritize reported CVEs by their Exploit Prediction Scoring System likelihood of real-world exploitation, rather than by CVSS severity alone');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eb0962e6-f50d-43c7-ae48-8d0140fc37b4', '363c75b1-7691-4d38-ab66-244551f2f8b5', 1, 'Set a hard limit on how many CVEs are displayed, regardless of severity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e46dd2fc-ebc4-4c61-aff6-747f0ff8965e', '363c75b1-7691-4d38-ab66-244551f2f8b5', 2, 'Filter results to only CVEs affecting the base image, excluding application layers');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7cbcd804-f9a8-41ea-8a53-cc1fabda4241', '363c75b1-7691-4d38-ab66-244551f2f8b5', 3, 'Convert the output into SARIF format automatically');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('01f6369f-22bf-4bf8-9808-cb5dab54f31a', 'b5a1a60d-53ab-48e2-9630-1dfc5eff4e14', 0, 'SARIF (Static Analysis Results Interchange Format) is a standard many CI/CD platforms and code-scanning dashboards (e.g. GitHub code scanning) can natively ingest and display');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ab7007f9-2aa9-4421-8638-d98fdd4a3ed7', 'b5a1a60d-53ab-48e2-9630-1dfc5eff4e14', 1, 'SARIF is required for Scout to run at all');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1eebfdaf-a414-4ac9-97c0-c91ec3217793', 'b5a1a60d-53ab-48e2-9630-1dfc5eff4e14', 2, 'SARIF format compresses the output to reduce storage costs');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2c2b3998-4df7-44db-9bb8-6d90f37029d9', 'b5a1a60d-53ab-48e2-9630-1dfc5eff4e14', 3, 'SARIF is the only format Scout supports for local images');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('271caff5-d189-4c4b-85f3-ef7f9a8e9642', '214f7b59-720d-4e4b-b8c9-946644d2e027', 0, 'The two tools check different things — DCT confirmed the image''s authenticity/integrity (who published it, unaltered), while Scout independently found real vulnerabilities in its actual package contents; a valid signature says nothing about vulnerability-free content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a7b94c96-fd17-4ebe-9f77-c86eeaa8be06', '214f7b59-720d-4e4b-b8c9-946644d2e027', 1, 'This is a contradiction that means one of the tools is misconfigured');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0117dc5e-9425-465c-9448-4db62340ddf5', '214f7b59-720d-4e4b-b8c9-946644d2e027', 2, 'Scout automatically revokes DCT signatures when it finds critical CVEs');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2604974b-03bb-4af5-9506-04bc757981b1', '214f7b59-720d-4e4b-b8c9-946644d2e027', 3, 'DCT signing implies Scout scanning was already run and passed');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7526ec9c-2a59-43ca-9eb3-942d973433d6', '83a5095e-08a0-475f-afaa-551a3c53f06f', 0, 'docker scan / Docker Security Scanning');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1e96ad7e-a575-4e5b-a8ba-f467aee96049', '83a5095e-08a0-475f-afaa-551a3c53f06f', 1, 'Docker Trusted Registry Insights');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d3ecb925-7257-41de-9b48-176fcfe9c7c4', '83a5095e-08a0-475f-afaa-551a3c53f06f', 2, 'Docker Bench for Security');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fe414980-9763-47c1-910e-f8142e324110', '83a5095e-08a0-475f-afaa-551a3c53f06f', 3, 'Notary Vulnerability Service');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f8589af1-20d9-4832-99d6-b9cc9b85ad62', '35dfee17-9494-4e11-8d09-2eb6170a45cd', 0, 'It''s mounted as a file under /run/secrets/<secret_name> in an in-memory (tmpfs) filesystem — unlike env vars, it isn''t captured by `docker inspect`, isn''t inherited by child processes automatically, and never touches disk');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4cd58e9a-c874-40af-b07f-d0b3212e0cbc', '35dfee17-9494-4e11-8d09-2eb6170a45cd', 1, 'It''s injected as a regular environment variable, identical to -e, but with an encrypted name');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('82e15182-b063-4eb5-9423-eec16199c187', '35dfee17-9494-4e11-8d09-2eb6170a45cd', 2, 'It''s written to a persistent named volume shared across all replicas');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('301b44f8-8d07-4141-9153-c8069bf2acb1', '35dfee17-9494-4e11-8d09-2eb6170a45cd', 3, 'It''s passed as a command-line argument to the container''s entrypoint');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9a423f54-b018-4126-a6f7-616e3fb0f783', 'dffd7c03-56c4-44df-aa7e-72b804a8d03c', 0, 'Environment variables are commonly captured in crash dumps, logged by process managers or `/proc/<pid>/environ`, and are often inherited by every child process spawned inside the container — a much larger accidental-exposure surface than a single, access-controlled file');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bb9c2690-1c40-4379-af2a-8d9af57f0d25', 'dffd7c03-56c4-44df-aa7e-72b804a8d03c', 1, 'Environment variables are always transmitted in plaintext over the network, while secrets are always encrypted in transit');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0caa4651-8264-49b2-a71e-b2ac25277d15', 'dffd7c03-56c4-44df-aa7e-72b804a8d03c', 2, 'Docker automatically encrypts environment variables at rest but not files');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('059e90cc-5240-4de0-8faa-a6392c723483', 'dffd7c03-56c4-44df-aa7e-72b804a8d03c', 3, 'There is no real difference — this is a common misconception');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3f6546e8-3f10-4d0a-ab10-d4d175d55845', 'a09f54e5-8769-47fb-afc5-2a0fda8bdf8e', 0, 'No — Docker secrets are a Swarm-services feature; a standalone container has no mechanism to mount a Swarm secret (bind-mounting a file or using --mount type=bind on a manually-managed file is the closest standalone equivalent, with none of the same access-scoping guarantees)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4c84a979-d220-4d85-86aa-b1df7d300246', 'a09f54e5-8769-47fb-afc5-2a0fda8bdf8e', 1, 'Yes, via the --secret flag on docker run, identical to service create');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8b1c2ad5-5c75-4c90-a1c8-4bb474fcf347', 'a09f54e5-8769-47fb-afc5-2a0fda8bdf8e', 2, 'Yes, but only if the container is run with --privileged');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('71122b4a-5271-4324-8607-0d62d9a713a4', 'a09f54e5-8769-47fb-afc5-2a0fda8bdf8e', 3, 'Yes, automatically, if the container''s image was built with a SECRET instruction in its Dockerfile');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d86c65c8-c1bb-4a45-bdc0-9c5743ff324c', '76d60c1a-4cfa-4d8d-b6f8-ae4c4ef1f46b', 0, 'Create a new secret under a new name/version (e.g. db_password_v2), then update the service to reference the new secret and remove the reference to the old one — Swarm reschedules tasks to pick up the new mount');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b9ea6eea-ffbe-4793-bd63-45cda7b39ee9', '76d60c1a-4cfa-4d8d-b6f8-ae4c4ef1f46b', 1, 'Run `docker secret update <name>` with the new value, which Swarm pushes to all running tasks live');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('33876cfe-d116-4d32-b197-c5479f7f4c14', '76d60c1a-4cfa-4d8d-b6f8-ae4c4ef1f46b', 2, 'Delete the old secret first; Swarm automatically regenerates it with prompted new input');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3ec3e369-f057-490c-8f36-979f85424f75', '76d60c1a-4cfa-4d8d-b6f8-ae4c4ef1f46b', 3, 'Restart the Docker daemon, which reloads all secrets from disk with new values');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c46d758c-839c-43ae-81b0-134a12634b64', 'e5d1d879-bc63-4fcb-80ce-e458b528f0ff', 0, 'It defaults to root ownership (UID 0) with mode 0444 (read-only); this can be overridden per-secret at service-create time with flags like --secret-uid, --secret-gid, and --secret-mode');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8f1b07dd-7e0b-4320-8623-56894176fd45', 'e5d1d879-bc63-4fcb-80ce-e458b528f0ff', 1, 'It always inherits the UID of the container''s ENTRYPOINT process automatically, with no way to override it');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bec9f2e9-fbf8-4f03-8074-2a6f7f6d3f0c', 'e5d1d879-bc63-4fcb-80ce-e458b528f0ff', 2, 'It is always world-writable (0666) for compatibility with non-root application processes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('18cb0d8c-e210-4e60-a192-7363bc8ebe21', 'e5d1d879-bc63-4fcb-80ce-e458b528f0ff', 3, 'Secret files have no concept of ownership or permissions; Docker enforces access purely at the network layer');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1e8cfde7-127b-465a-92ab-f2e6e24a8ced', '4766afe6-61bc-416e-8333-bff97d5bb182', 0, 'Configs are for non-sensitive data (e.g. an nginx.conf template) and are NOT encrypted at rest in the same access-restricted way secrets are, while secrets are specifically for sensitive material with tighter access controls');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9b0e5aeb-5f95-4aa6-821b-afe81c84a103', '4766afe6-61bc-416e-8333-bff97d5bb182', 1, 'Configs and secrets are functionally identical; ''config'' is simply an older, deprecated name for ''secret''');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8f3b13c4-8a67-4ab6-80ba-b4942d06fb3f', '4766afe6-61bc-416e-8333-bff97d5bb182', 2, 'Configs can only be used with Kubernetes-backed MKE clusters, never plain Swarm');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0c599fac-07e4-4e70-b72a-2c1fe93fd55d', '4766afe6-61bc-416e-8333-bff97d5bb182', 3, 'Configs are mutable in place, while nothing else about them differs from secrets');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c5ad6008-41ac-41bf-b73d-1b78f5936630', '86502036-9337-4c3b-82c5-0b10220ed293', 0, '`docker stack deploy` reads the referenced local file once at deploy time and creates a genuine Swarm secret object from its content — the plaintext file on the deploying host is a one-time input, not something Swarm continues to reference');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bb4f112a-ad29-4ca7-b43a-cf563a3526b8', '86502036-9337-4c3b-82c5-0b10220ed293', 1, 'The file path itself is bind-mounted read-only into every replica directly from the deploying host''s disk');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('73ae001d-24c8-41e5-b125-7ba10fc977c9', '86502036-9337-4c3b-82c5-0b10220ed293', 2, 'Compose secrets are purely cosmetic in stack deploys and are silently ignored; only docker secret create populates real secrets');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8ce1174d-c8de-4584-9a88-3319c3593773', '86502036-9337-4c3b-82c5-0b10220ed293', 3, 'The file is embedded directly into the image at the next `docker build`');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('014f2559-e37f-4030-be3b-87234017334c', 'de928c55-f855-403f-bcd1-8dab86aaa1d1', 0, 'The default profile already blocks a broad set of dangerous syscalls (around 44 by default) as a sane baseline for all containers; a custom profile lets you further restrict (or, less commonly, loosen) exactly which syscalls a specific container''s process is permitted to make, tailored to what that application actually needs');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e2dcec54-79d9-4340-a708-9b573fb79e52', 'de928c55-f855-403f-bcd1-8dab86aaa1d1', 1, 'The default profile allows all syscalls; only a custom profile enables any blocking at all');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8fad6b2b-8939-4d54-8dca-012d059e7651', 'de928c55-f855-403f-bcd1-8dab86aaa1d1', 2, 'seccomp only takes effect if AppArmor is disabled first');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9295cbbb-ca54-49a5-9fa1-dfdbf301b51e', 'de928c55-f855-403f-bcd1-8dab86aaa1d1', 3, 'Custom seccomp profiles can only add permitted syscalls, never remove any that the default already allows');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e83cfd27-16ba-4d71-affe-edfcfd0f1cfc', 'fe99344e-05b0-4db6-9eaf-b66e619ef6dc', 0, 'It disables seccomp filtering entirely for that container, allowing it to make any syscall the kernel/other isolation layers (capabilities, AppArmor, etc.) don''t otherwise block — this significantly increases kernel-attack surface and should only be used when a specific, understood syscall need requires it');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1308febe-cdfa-4128-98ff-0e639478e38f', 'fe99344e-05b0-4db6-9eaf-b66e619ef6dc', 1, 'It applies the strictest possible seccomp profile, blocking every syscall except a minimal allowlist');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d9acf5e2-330a-4988-bfb8-fcba516a97e3', 'fe99344e-05b0-4db6-9eaf-b66e619ef6dc', 2, 'It only disables seccomp for the container''s init process (PID 1), not its child processes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('06936532-d73c-4efd-a323-f9953f3e6dee', 'fe99344e-05b0-4db6-9eaf-b66e619ef6dc', 3, 'It is the default setting for all containers unless overridden');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('87cb2ceb-23c4-46c1-b911-e89c482890e9', '932faf59-b35b-42e0-95af-06085b777df2', 0, 'seccomp restricts which syscalls a process may invoke at all (syscall-number granularity); AppArmor is a Mandatory Access Control (MAC) system that additionally restricts what a process can do with specific resources (e.g. which files/paths it may read/write/execute, network access), using named profiles per-binary or per-container');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('17b73603-8fd8-448e-beb2-449c053af925', '932faf59-b35b-42e0-95af-06085b777df2', 1, 'They are functionally redundant; enabling one automatically disables the other');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0f70ff79-c89a-430a-9e4c-636a29fb6a92', '932faf59-b35b-42e0-95af-06085b777df2', 2, 'AppArmor only works on Fedora/RHEL-family kernels while seccomp only works on Debian/Ubuntu-family kernels');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ba6e2767-d2d6-4edb-99a0-e318de8e7a43', '932faf59-b35b-42e0-95af-06085b777df2', 3, 'seccomp controls network access exclusively; AppArmor controls filesystem access exclusively, with no overlap');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e91cfba4-2258-41c0-b386-7b37bcacfa16', '19033d80-8653-431a-93ec-5964c4ca69b2', 0, 'Docker applies its own default profile (docker-default), which restricts a range of actions (like mounting most filesystems and loading kernel modules) without requiring any manual configuration');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fded07a0-6c9d-4039-bc09-9c5c66616ade', '19033d80-8653-431a-93ec-5964c4ca69b2', 1, 'No AppArmor confinement is applied unless the operator explicitly specifies one with --security-opt apparmor=...');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5e852393-9e2b-4b1b-9957-72d5892fc374', '19033d80-8653-431a-93ec-5964c4ca69b2', 2, 'AppArmor is applied only to Swarm services, never to standalone containers');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c5bd2224-0ebc-4a8e-98f5-addff4cf5877', '19033d80-8653-431a-93ec-5964c4ca69b2', 3, 'The container inherits the AppArmor profile of the process that invoked `docker run`, not a Docker-specific one');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1706b8a2-e451-4ade-8448-0f14e54eb2fb', 'ddfe013e-8c2c-456e-afed-e5e92b27af1e', 0, 'Yes — they operate at different layers (syscall-level vs. resource/MAC-level) and are commonly combined for defense-in-depth, alongside Linux capabilities dropping');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('81c9efbb-d5e1-4de1-8f89-9cbe20b587b8', 'ddfe013e-8c2c-456e-afed-e5e92b27af1e', 1, 'No — Docker only allows one security module to be active per container, and AppArmor takes precedence if both are specified');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('246227bb-e509-4c06-8c14-8ff1d644d426', 'ddfe013e-8c2c-456e-afed-e5e92b27af1e', 2, 'No — specifying both causes the container to fail to start with a conflict error');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4575d0c4-ee7f-4ae9-9a61-3677cd590dda', 'ddfe013e-8c2c-456e-afed-e5e92b27af1e', 3, 'Yes, but only on hosts running SELinux, since SELinux arbitrates between the two');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bdfe433c-f27b-4e81-9de5-67c49747c108', '8926adf9-0f28-4b05-bcf1-ae947f7054ac', 0, 'In rootless mode, BOTH the Docker daemon and the containers it runs operate entirely without root privileges on the host; with userns-remap, the daemon itself still runs as root, and only the container''s UID namespace is remapped so its ''root'' maps to an unprivileged host UID');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e0bed207-69d4-4c66-bf21-2e326f92ea2b', '8926adf9-0f28-4b05-bcf1-ae947f7054ac', 1, 'They are interchangeable names for the same feature');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('88d1cce6-4776-4536-8816-e82cb1366aa8', '8926adf9-0f28-4b05-bcf1-ae947f7054ac', 2, 'userns-remap runs everything rootless, while rootless mode still requires a root-owned daemon process');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('35cb84e7-9347-4510-b188-8acd2abd47d5', '8926adf9-0f28-4b05-bcf1-ae947f7054ac', 3, 'Rootless mode only affects networking; userns-remap only affects filesystem permissions');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b1f70fe5-68ad-4d68-b8d9-ff45cda17fbd', 'a1f3fdec-e49e-4c19-a554-cf031f1c6ef4', 0, 'No — userns-remap is not a supported configuration under rootless mode per current Docker documentation; attempting to combine them is not a supported setup');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ef0605e8-b2e6-48cd-8da1-221264816094', 'a1f3fdec-e49e-4c19-a554-cf031f1c6ef4', 1, 'Yes, and this combination is Docker''s officially recommended hardened configuration');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9155d4a0-7c57-4fa4-8ad8-261a54a00f52', 'a1f3fdec-e49e-4c19-a554-cf031f1c6ef4', 2, 'Yes, but only when using the overlay2 storage driver');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('69908c5d-1d22-4cc0-8843-7f3c1a0506f6', 'a1f3fdec-e49e-4c19-a554-cf031f1c6ef4', 3, 'This combination is required for Swarm mode to function correctly');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f8182a1d-d691-47dd-a83a-2156448fc38a', '72d324b7-919c-4d1f-ae13-bfd080b1554c', 0, 'Certain features that require elevated host privileges — such as some network drivers, cgroup-based resource limiting on older kernels/cgroup configurations, and binding to privileged (< 1024) ports without extra setup — are restricted or require workarounds');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4c6e2467-d82d-476d-85a9-73693dffe8e5', '72d324b7-919c-4d1f-ae13-bfd080b1554c', 1, 'Rootless mode cannot run any container images at all, only Dockerfiles built with a ROOTLESS instruction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7f0c181f-a7c6-463b-a2e7-cd6c06cece79', '72d324b7-919c-4d1f-ae13-bfd080b1554c', 2, 'Rootless mode disables image layer caching entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0b38a3c1-1c21-4b13-a83b-a0d9b3b5c2f2', '72d324b7-919c-4d1f-ae13-bfd080b1554c', 3, 'Rootless mode cannot be used with Docker Compose under any circumstances');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('02307d9c-287a-4314-a219-e82ca9155ec0', 'd5308355-90bf-4da2-aeee-d16d98c67b88', 0, 'UID 0 inside the container is mapped to a non-zero, unprivileged UID range on the host, so even a process that gains ''root'' inside the container has no genuine root privileges on the underlying host');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0ee9420c-48a1-4345-9d90-7edb9830a006', 'd5308355-90bf-4da2-aeee-d16d98c67b88', 1, 'It disables the concept of UID 0 entirely, so no process inside any container can ever be UID 0');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('32a461a7-61d6-482e-accd-315b5e4a928b', 'd5308355-90bf-4da2-aeee-d16d98c67b88', 2, 'It only remaps GIDs, leaving UID mapping untouched');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c9043b80-615f-452b-81fb-30a28d36a1ff', 'd5308355-90bf-4da2-aeee-d16d98c67b88', 3, 'It changes the host''s own root UID to a different value');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6e6f0593-37bf-4c08-b5d6-feac6b68e21a', '00e6cbdb-712f-4343-852f-2bd9a16fd770', 0, 'A container-breakout vulnerability that would otherwise grant the attacker genuine host-root, instead only grants the attacker the unprivileged remapped host UID — substantially limiting post-breakout impact');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7bb5e78f-7664-44ea-a5e4-9463749aad64', '00e6cbdb-712f-4343-852f-2bd9a16fd770', 1, 'SQL injection attacks against an application running inside the container');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3f6292e7-d8de-4b58-bcd0-37317be52648', '00e6cbdb-712f-4343-852f-2bd9a16fd770', 2, 'Man-in-the-middle attacks against the container''s outbound network traffic');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1a9aa8a6-8a9e-4dc6-9cf9-a83fb8a78f41', '00e6cbdb-712f-4343-852f-2bd9a16fd770', 3, 'Supply-chain attacks where a malicious base image is pulled from a public registry');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bc30e85f-69f5-48cd-bbac-6e41909ed783', '7bfa67c8-5162-4f0d-acfe-c3d210ab44b6', 0, 'Anyone who can reach that port has unauthenticated root-equivalent control of the host, since the Docker API allows actions like mounting the host filesystem into a container — this port should never be exposed without TLS client-certificate authentication');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('28912163-7510-4840-a54a-4312ccbd33da', '7bfa67c8-5162-4f0d-acfe-c3d210ab44b6', 1, 'The connection is automatically encrypted with TLS by default, but not authenticated');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d782a8b4-360d-457b-b76c-54289e4d5991', '7bfa67c8-5162-4f0d-acfe-c3d210ab44b6', 2, 'Only local (127.0.0.1) clients can connect, regardless of the bind address');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a0eac1fd-221c-4c7f-8f74-ee0deff66395', '7bfa67c8-5162-4f0d-acfe-c3d210ab44b6', 3, 'Docker requires a username/password over this port even without extra configuration');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8435b583-581f-4865-bd50-eae6a1e19dc2', '7f3f5b55-c6d5-4fa1-98b8-19692831e9f4', 0, '2376');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cc3fb9e8-3ea5-4b5c-99b6-404d2afc0425', '7f3f5b55-c6d5-4fa1-98b8-19692831e9f4', 1, '2375');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('79b374ee-0b28-48fd-bb8d-d5041baecf95', '7f3f5b55-c6d5-4fa1-98b8-19692831e9f4', 2, '8080');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cca99b22-f900-465d-9b07-d01356a0431c', '7f3f5b55-c6d5-4fa1-98b8-19692831e9f4', 3, '443');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2ea8297d-4252-41cd-a6a4-2c5d724bede3', 'bab80b80-cc62-499f-8b09-3e10e2a3738c', 0, 'It requires connecting clients to present a certificate signed by a trusted CA, so only clients holding a valid client certificate can authenticate to the daemon at all — not just encrypting traffic, but authenticating who''s allowed to connect');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a8715c3c-3dee-4dfe-b9db-ea958011d46b', 'bab80b80-cc62-499f-8b09-3e10e2a3738c', 1, 'It only encrypts traffic; any client can still connect without a certificate');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1661e2f6-fbed-4504-a0f3-bdbd0139eadf', 'bab80b80-cc62-499f-8b09-3e10e2a3738c', 2, 'It restricts connections to the local host only, regardless of the bind address');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('356b45d9-24fa-4788-a79c-e04896c68c0d', 'bab80b80-cc62-499f-8b09-3e10e2a3738c', 3, 'It disables the REST API entirely in favor of a gRPC-only interface');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('71916b5a-3afe-484e-bb78-e7e6a3936691', '5850ef15-3f27-4a7f-8de6-1a0eba787c90', 0, 'Yes — Docker treats any registry without valid TLS as insecure by default and refuses to communicate with it unless that registry is explicitly added to the daemon''s ''insecure-registries'' allowlist');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('40bbe35c-a0d6-45b9-94f3-7f0b36b73546', '5850ef15-3f27-4a7f-8de6-1a0eba787c90', 1, 'No — Docker communicates with any registry over HTTP by default with no special configuration required');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('da967cc4-a221-466d-86cd-5c3cf5f47dee', '5850ef15-3f27-4a7f-8de6-1a0eba787c90', 2, 'Only Docker Hub enforces TLS; self-hosted registries are always allowed over plain HTTP');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('920919c3-2d54-4711-9e10-aaa1d69d4918', '5850ef15-3f27-4a7f-8de6-1a0eba787c90', 3, 'TLS is only enforced for docker push, never for docker pull');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ae4bd138-3e83-4206-965f-e69b7000c830', '711a1130-24cf-4e8c-8d24-7aa82ada2c9a', 0, 'The internal CA''s certificate must be placed under /etc/docker/certs.d/<registry-host:port>/ca.crt on each host so the daemon trusts it for that specific registry, without disabling TLS verification globally');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4512797b-ffe4-4e07-b78b-8b6db875087a', '711a1130-24cf-4e8c-8d24-7aa82ada2c9a', 1, 'Nothing — Docker automatically trusts any certificate presented by a registry on first connection (trust-on-first-use)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f86723c9-bd5e-49ca-a6e3-1fee003efd19', '711a1130-24cf-4e8c-8d24-7aa82ada2c9a', 2, 'The registry must be added to /etc/hosts with a special docker-trusted alias');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ac8acd32-cee3-4be2-be9e-2f1da10a087b', '711a1130-24cf-4e8c-8d24-7aa82ada2c9a', 3, 'The daemon must be restarted with --tlsverify=false globally');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f5de2659-1bd7-42d5-82d7-eb6f6e18e088', 'a8c29688-21cd-42ea-bbd5-593699a49f93', 0, 'Under /etc/docker/certs.d/<registry-host:port>/, alongside any CA cert, using files with .cert and .key extensions');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2d03cb84-2c59-4519-8e69-cc73934c8bf3', 'a8c29688-21cd-42ea-bbd5-593699a49f93', 1, 'In the user''s ~/.docker/config.json credential store exclusively, with no filesystem cert lookup');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e471861d-b265-41d3-b8f5-75e0114fdad5', 'a8c29688-21cd-42ea-bbd5-593699a49f93', 2, 'Client certificates aren''t supported for registry authentication at all — only username/password or token auth');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('37afe426-3436-4ace-8703-e14089554713', 'a8c29688-21cd-42ea-bbd5-593699a49f93', 3, 'In the same location as the daemon''s own TLS certs (/etc/docker/tls/), regardless of which registry is being accessed');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
